package io.github.jesterportfolio.hearth.story;

import io.github.jesterportfolio.hearth.world.TemplateStore;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

final class StoryTemplateSourceTest {
    @TempDir Path temp;
    Path source()throws Exception{var p=temp.resolve("source");Files.createDirectories(p.resolve("region"));Files.writeString(p.resolve("region/r.0.0.mca"),"synthetic spatial envelope");Files.writeString(p.resolve("worldguard-regions.yml"),"regions: {}\n");Files.createDirectories(p.resolve("data/paper"));Files.writeString(p.resolve("data/paper/metadata.dat"),"source identity");Files.createDirectories(p.resolve("playerdata"));Files.writeString(p.resolve("playerdata/private.dat"),"source personal sentinel");return p;}
    StoryPreparationSettings.Job job(Path p)throws Exception{return new StoryPreparationSettings.Job("one",UUID.randomUUID(),"hearth_story:one","source","v1",new TemplateStore().digest(p),StoryTemplateSource.hash(p.resolve("worldguard-regions.yml")),0.5,65,0.5,0,0,Set.of("protected"));}
    Path destination()throws Exception{var p=temp.resolve("new");Files.createDirectories(p.resolve("data/paper"));Files.writeString(p.resolve("data/paper/metadata.dat"),"new identity");return p;}
    @Test void spatialAndProtectionCopyNeverClonesIdentityOrPersonalData()throws Exception{var p=source();var j=job(p);var source=StoryTemplateSource.inspect(temp,j,10,10000);var target=destination();var region=temp.resolve("target-regions.yml");source.copy(target,region,null);assertEquals("new identity",Files.readString(target.resolve("data/paper/metadata.dat")));assertFalse(Files.exists(target.resolve("playerdata/private.dat")));assertEquals(j.spatialHash(),new TemplateStore().digest(target));assertEquals(j.regionHash(),StoryTemplateSource.hash(region));assertEquals(j.spatialHash(),new TemplateStore().digest(p));assertEquals("source identity",Files.readString(p.resolve("data/paper/metadata.dat")));}
    @Test void changedSourceRefusesBeforeDestinationWrites()throws Exception{var p=source();var source=StoryTemplateSource.inspect(temp,job(p),10,10000);Files.writeString(p.resolve("region/r.0.0.mca"),"changed source");var target=destination();assertThrows(Exception.class,()->source.copy(target,temp.resolve("target-regions.yml"),null));assertFalse(Files.exists(target.resolve("region")));assertEquals("new identity",Files.readString(target.resolve("data/paper/metadata.dat")));}
    @Test void existingProtectionWithoutOwnedInitialHashIsPreserved()throws Exception{var p=source();var source=StoryTemplateSource.inspect(temp,job(p),10,10000);var target=destination();var region=temp.resolve("target-regions.yml");Files.writeString(region,"existing protection");assertThrows(Exception.class,()->source.copy(target,region,null));assertEquals("existing protection",Files.readString(region));assertFalse(Files.exists(target.resolve("region")));}
    @Test void changedOwnedProtectionIsNotOverwritten()throws Exception{var p=source();var source=StoryTemplateSource.inspect(temp,job(p),10,10000);var target=destination();var region=temp.resolve("target-regions.yml");Files.writeString(region,"fresh empty protection");var expected=StoryTemplateSource.hash(region);Files.writeString(region,"unexpected change");assertThrows(Exception.class,()->source.copy(target,region,expected));assertEquals("unexpected change",Files.readString(region));}
    @Test void fileAndByteLimitsApplyBeforeCopy()throws Exception{var p=source();var j=job(p);assertThrows(Exception.class,()->StoryTemplateSource.inspect(temp,j,1,10000));assertThrows(Exception.class,()->StoryTemplateSource.inspect(temp,j,10,1));}
    @Test void symlinkCannotEscapeBudget()throws Exception{var p=source();var j=job(p);var outside=temp.resolve("outside.dat");Files.writeString(outside,"outside preserved");Files.createSymbolicLink(p.resolve("region/link.mca"),outside);assertThrows(Exception.class,()->StoryTemplateSource.inspect(temp,j,10,10000));assertEquals("outside preserved",Files.readString(outside));}
    @Test void nestedSpatialDirectoryIsRefusedBeforeUnboundedTraversal()throws Exception{var p=source();var j=job(p);Files.createDirectories(p.resolve("region/nested"));assertThrows(Exception.class,()->StoryTemplateSource.inspect(temp,j,10,10000));}
    @Test void futureDestinationChecksExistingParentWithoutCreatingIt()throws Exception{var target=temp.resolve("namespace/not-yet-created");StoryTemplateSource.requireSpace(target,1,1);assertFalse(Files.exists(temp.resolve("namespace")));assertThrows(ArithmeticException.class,()->StoryTemplateSource.requireSpace(target,Long.MAX_VALUE,1));}
    @Test void destinationAliasAndExistingFileArePreserved()throws Exception{var file=temp.resolve("original.dat");Files.writeString(file,"original");assertThrows(Exception.class,()->StoryTemplateSource.requireSpace(file,1,1));var link=temp.resolve("alias");Files.createSymbolicLink(link,temp);assertThrows(Exception.class,()->StoryTemplateSource.requireSpace(link.resolve("new"),1,1));assertEquals("original",Files.readString(file));}
    @Test void missingEntryRegionAndIncorrectProtectionHashAreRejected()throws Exception{var p=source();var j=job(p);var wrong=new StoryPreparationSettings.Job(j.id(),j.run(),j.key(),j.template(),j.version(),j.spatialHash(),"f".repeat(64),j.x(),j.y(),j.z(),j.yaw(),j.pitch(),j.regions());assertThrows(Exception.class,()->StoryTemplateSource.inspect(temp,wrong,10,10000));Files.move(p.resolve("region/r.0.0.mca"),p.resolve("region/r.1.0.mca"));assertThrows(Exception.class,()->StoryTemplateSource.inspect(temp,job(p),10,10000));}
}
